import{_ as i,o as a,c as t,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.6 Automatic Maximum Gross Production","description":"","frontmatter":{"translationSource":{"title":"1.6智能最大毛产","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}]]},"headers":[],"relativePath":"full-storage-oscillation-plan.md","filePath":"logistics/src/page-JEibHxjUhjwaznRy5jp6oc.md"}'),n={name:"full-storage-oscillation-plan.md"};function s(r,e,l,p,d,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="_1-6-automatic-maximum-gross-production" tabindex="-1">1.6 Automatic Maximum Gross Production <a class="header-anchor" href="#_1-6-automatic-maximum-gross-production" aria-label="Permalink to &quot;1.6 Automatic Maximum Gross Production&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-14. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>JEibHxjUhjwaznRy5jp6oc</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-red"><strong>#言: Where&#39;s my Xiranite module?</strong></span></p><p>Requirements:</p><p>Jingyu Valley: 12 Xiranite units with two Depot Loader inputs each. The self-starting plan with 12 such units and 9 Control Ports is ready. Cursed-engineering point: the facility count has exploded.</p><p>Other sections:</p><p>Yinglung Pass: remove Xiranite oversupply, place the automatically connected conduits outside, and add things (Separator Cores).</p><p>The main base needs compression (Refining Units, Sewage-treatment trash can, Xircon line, Ferrium refining/shredding and Separator Cores, half-rate batteries/, Xiranite oscillation/, Xiranite fluid-gas transmutation/, Xiranite bus/, Heavy Xiranite/).</p><p><span id="source-block-wt8iPy0gMDFywV7KEmhkoR"></span></p><h2 id="video-script" tabindex="-1">Video Script <a class="header-anchor" href="#video-script" aria-label="Permalink to &quot;Video Script&quot;">​</a></h2><p><span id="source-block-YS3tBMxxg8McQAfMF35GpN"></span></p><h3 id="production-line-showcase" tabindex="-1">Production Line Showcase <a class="header-anchor" href="#production-line-showcase" aria-label="Permalink to &quot;Production Line Showcase&quot;">​</a></h3><p>How this generation surpasses the previous one</p><p>A more detailed feature introduction, especially a demonstration of the add-ons</p><p>Expectations for the audience: to leave positive comments in the comment section, for example; to bring most questions to the Q&amp;A site and the group chats, and to make clear that we lack the capacity to answer each one individually; and, on noticing that the comment section and even group members contain many incorrect replies, to affirm the helpful spirit first, then point out that wrong replies cause confusion, and finally not to condemn anyone outright but to further suggest that anyone with questions go to the group or the Q&amp;A site and treat the Q&amp;A staff&#39;s answers as authoritative—the staff may not be absolutely correct, but it is undeniable that they are more familiar with the production line than most people and can pass questions on to the developers at any time.</p><p><span id="source-block-UU4P5kkrLs4f54xy23COub"></span></p><h3 id="production-line-explanation" tabindex="-1">Production Line Explanation <a class="header-anchor" href="#production-line-explanation" aria-label="Permalink to &quot;Production Line Explanation&quot;">​</a></h3><p>Module overview</p><p>Explanation of the automatic-balancing path</p><p><span id="source-block-VjRatZPY7VytfwEPSU53Zl"></span></p><h3 id="installation-tutorial" tabindex="-1">Installation Tutorial <a class="header-anchor" href="#installation-tutorial" aria-label="Permalink to &quot;Installation Tutorial&quot;">​</a></h3><p><span id="source-block-0rfOwq29K0j4iJLxK2zROW"></span></p><h2 id="production-line-layout" tabindex="-1">Production Line Layout <a class="header-anchor" href="#production-line-layout" aria-label="Permalink to &quot;Production Line Layout&quot;">​</a></h2><p><span id="source-block-pZevVPXGlCFmWxYpA22zV7"></span></p><h3 id="jingyu-valley" tabindex="-1">Jingyu Valley <a class="header-anchor" href="#jingyu-valley" aria-label="Permalink to &quot;Jingyu Valley&quot;">​</a></h3><p><span class="mark-red">Notes for the Jingyu Valley guided-placement script: because of Depot Loader priorities, once the Automation-Core is placed, neither its orientation nor its output item may be changed. Make absolutely sure it faces the direction you want (this affects the teleport arrival point and therefore the distance to the zipline) and outputs the correct item. Any change requires replacing the Loaders in the Liquid Xiranite oscillation module / placing the main base again. (But output labels can normally be deleted—wait, can they? Assume not for now. If you want to delete an output label, do it while placing Jingyu Valley, and place power generation first too.</span></p><p><strong>Current main constraint: 288 facilities (the facility count excludes pipes, pipe components and conveyor belts).</strong></p><p>12 Xiranite units with two Depot Loader inputs each (required)</p><p>2 Separator Cores (required)</p><p>3 Cuprium refining setups (oversupplied depot input, overflow shredding and fixed shredding all work and can be combined; a total of 2 Shredding Units would be excellent) (required)</p><p>Self-starting Yazhen/Jincao planting–seed-picking–shredding groups, one belt each (required)</p><p>Ferrium: 4 Refining Units with overflow to 3 Shredding Units</p><p>Fitting Units: 3 Pyrrolite, 1 Hetonite, 1 Ferrium</p><p>Pyrrolite Component Gearing Unit</p><p>SC Wuling Batteries (optional) (can be Sandleaf or Packaging)</p><p><span id="source-block-DWQoslYRbo23aoBVXH3XsK"></span></p><h4 id="blueprints" tabindex="-1">Blueprints <a class="header-anchor" href="#blueprints" aria-label="Permalink to &quot;Blueprints&quot;">​</a></h4><p><span class="mark-red">When saving a plan here, remember to mark which of the modules listed above are missing.</span></p><p>Oh no, it&#39;s painful without pictures. Should I import them all again? Or could you take screenshots and post them? TAT</p><p>Candidate results</p><p><span id="source-block-cQfQ9Yze9mNszYCHirnvQO"></span></p><h5 id="_13x286" tabindex="-1">13x286 <a class="header-anchor" href="#_13x286" aria-label="Permalink to &quot;13x286&quot;">​</a></h5><p>EF01o5u21aiU362EIieO</p><p>EF01A67024u8eEUI9ieO</p><p>EF014AE7uI60O3eIE71A 175; missing two Clean Water labels. Note: no Ferrium Parts.</p><p><span id="source-block-yGLCLRondLTdDxYZtwQJZU"></span></p><h5 id="ss" tabindex="-1">SS <a class="header-anchor" href="#ss" aria-label="Permalink to &quot;SS&quot;">​</a></h5><p>EF015i2O176iIuoeIoe</p><p>EF01ao60534oiA0oe5e</p><p>EF015i2O176iIu4eIoe 175. Note: no Ferrium Parts.</p><p>13x286 revision 1: 176; added one water supply for shredding, corrected plant placement for shredder warm-up, and added a Ferrium Parts Fitting Unit. Only the top and middle blueprints changed.</p><p>EF013Eo5097iIaAA0579</p><p>EF01U9eaE23oiO3I7Oa8</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-53917257dfbc9a54.q90-00f2379f6eb994aa.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-oGV4w9c54tkzUyK73km3p4"></span></p><h5 id="bear" tabindex="-1">bear <a class="header-anchor" href="#bear" aria-label="Permalink to &quot;bear&quot;">​</a></h5><p>EF015i2UO2EA1ua0eIoe</p><p>EF012UOe4O579855eIOo</p><p>EF014AE75EOU637UEa1A 178; includes a zipline support, complete labels and room for conduits. Note: no Ferrium Parts.</p><p>#言, comment: I&#39;m wondering whether one label could serve two pumps, which would make the manifold conduits easier to route. The advantages are room for 3 Thermal Banks and a very tidy layout.</p><p>SS revision 1: corrected water-pipe connections, moved the four essential conduits to matching positions on the same side, corrected some misconnected belts, and assigned one label per water supply.</p><p>EF01I43u18ui196U5o08</p><p>EF015i24oE4aouUEeIoe</p><p>EF01i1UA57Ao522U72U4</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7b7fba96431422e1.q90-208d72bdd3b7f208.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-zxUbO227j3Kb2WzqIHNVdW"></span></p><h5 id="collaboration-between-f-e-i-and-13×286" tabindex="-1">Collaboration between F.E.I. and 13×286 <a class="header-anchor" href="#collaboration-between-f-e-i-and-13×286" aria-label="Permalink to &quot;Collaboration between F.E.I. and 13×286&quot;">​</a></h5><p>EF01u28358Aiu09uAoOU</p><p>EF018OIo2I7U81u1UI73</p><p>EF01081au1E20i30E179; borrowed inspiration, 159, complete labels, 1 conduit and a zipline.</p><p>13x286 11.1</p><p>Fixed some small mistakes, such as a Protocol Stash placed instead of a Refining Unit, and one water pipe serving five facilities.</p><p>This blueprint now meets all requirements and is far ahead in facility-count compression. We can crown it king.</p><p>Note that this is the equivalent facility count. The conveyor-belt allowance has already been exceeded, so adding more facilities will make the count shoot up.</p><p>Revised twice now; I also ended up with one water pipe serving five facilities. Fixed(?) the four-items/one-second-stall problem. There is space to add Control Ports and water bottles as water-connection markers. Xiranite reaches full production in about seven minutes; the key to speeding it up is water for the Planting Unit at the far upper left.</p><p>Removed all water-pipe labels because they may cause the four-items/one-second stall when offline? Water-bottle labels were not added either. The 12 water pipes plus Inergen, the extra conveyor belts for individual Control Ports, and the labels would immediately use up another 16 facilities.</p><p>EF013Eo5097iIa3a0579</p><p>EF01eaA65OouU4OaoAi8</p><p>EF014AE7uI60O3uUE71A</p><p>The blueprint includes 153 equivalent facilities, a pipe-facility count of 26, and 46 minus water pipes [source shorthand]. It is fully functional, leaves an unfilled zipline space, and contains no logistics bridges. Supporting facilities are 4 pylons to power 12 water pumps, a pair of two-port conduits, the corresponding 11 water pipes and 3 Pipe Convergers. For frequent disassembly, conduit relays can be used at the cost of 4 extra facilities (two conduit sets). A manifold conduit can be replaced by two full-rate single-port conduits.</p><p>Note: I added the Ferrium return-to-depot route before the Parts Fitting Unit at the lower left myself. It is not functionally necessary and is not in the blueprint.</p><p>Changed Cuprium to be shredded first, with overflow going to the depot. Tidying this up saved another 1 facility and 1 pipe facility.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-811e996b30f8f0e1.q90-bae9cac359973699.webp" alt="16 Automatic Maximum Gross Production"></p><p>SS revision three: 君 said overflow shredding and extra Ferrium Parts were unnecessary, so these were removed; some structures were optimized, and all exposed-pipe connections are conveniently positioned. Compressed into two blueprints with placement safeguards: both are 50*50, need no particular placement order, and cannot be placed the wrong way.</p><p>[Super Jingyu Valley 1] EF012UOEu5E6u899eIOo</p><p>[Super Jingyu Valley 2] EF015i24oE4aou2UeIoe</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-14ff90d6de20dc3e.q90-f9c9c563815492b6.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>13x286: Another revision, anyway. This is a temporary blueprint, pending someone fitting the Inergen conduit rerouting into it as well. The Clean Water conduit is also awkwardly positioned and needs extra piping. Its single label cannot be distinguished from an ordinary pump label, even though the conduit needs a full-rate water pipe.</p><p>EF01I43E61A789i65o08</p><p>EF01o5u21aiU36U0IieO</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e962b0c5906d166e.q90-c334c2491fb8e0d5.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>From SSnighter &amp; F.E.I &amp; 君 &amp; 13x: Revision complete. The conduit rerouting is at the lower left; an upper-left version also exists. It still uses the originally planned 11.5 pumps, with nowhere to use the spare half-pump. We have tried to keep placement to two blueprints.</p><p>Left: 62 machines, 97 other components (39 belts + 27 pipe components + 31 pipes).</p><p>Right: 89 machines, 71 other components (67 belts + 4 pipe components + 0 pipes).</p><p>Total: machines (151/288), other components (162/256), belts (106/96), pipe components (31/64), pipes (31/96). Actual machine usage: 151+10=161 machines. Including supporting AIC facilities—4 power poles + 12 pumps + 4 conduits—the total is 181 machines.</p><p>[Jingyu Valley left] EF01ao6uie529A25oe5e</p><p>[Jingyu Valley right] EF01A67024u8eEua9ieO</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1ba2d8708f9f409f.q90-a00d8fe2f36ff702.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a1abd4a8b759ed20.q90-6fb80479ee77e3d5.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Old blueprints retained for reference:</p><p>13x286. Note: no Gearing Unit.</p><p>EF01I43E61A789E25o08</p><p>EF01I43E61A789Eu5o08</p><p>EF01ao6uie529AO7oe5e</p><p><span id="source-block-tkw1iLW0nUBPYwoeRyJccp"></span></p><h3 id="main-base" tabindex="-1">Main Base <a class="header-anchor" href="#main-base" aria-label="Permalink to &quot;Main Base&quot;">​</a></h3><p>Liquid Xiranite oscillation (4 crucibles<br> Input — water — by the river. Output — Liquid Xiranite — Xiranite Fluid-Gas Transmuting Unit.</p><p>2 fixed crucibles, requiring mixed medicine and one agricultural by-product<br> Input — water — by the river. Output — Liquid Xiranite — Xiranite Fluid-Gas Transmuting Unit. Output — medicinal fluid — basic-medicine line.</p><p>Mixed Xiragen/Aquagen production<br> Input — Liquid Xiranite — 2 fixed crucibles. Input — water — by the river / relayed through another water conduit. Output — Liquid Xiranite —</p><p>All-Condition Xircon</p><p>Cuprium refining with overflow to shredding: 8</p><p>Cuprium refining with two belts: 4</p><p>Cuprium refining with two belts, 2 coupled trash cans</p><p>Basic-medicine line starting from Ferrium</p><p>SC Wuling Batteries</p><p><span id="source-block-krXKbnL5O0kAIMgiAR5mXr"></span></p><h3 id="yinglung-pass" tabindex="-1">Yinglung Pass <a class="header-anchor" href="#yinglung-pass" aria-label="Permalink to &quot;Yinglung Pass&quot;">​</a></h3><p>Conduits placed outside — Solid-Gas Transmuting Units switched to overflow, plus Separator Cores</p><p><span id="source-block-Ces5lBPzmHuwJoEt14KUwj"></span></p><h4 id="blueprints-1" tabindex="-1">Blueprints <a class="header-anchor" href="#blueprints-1" aria-label="Permalink to &quot;Blueprints&quot;">​</a></h4><p>Arknights: Endfield blueprint [1], share code EF012UOe9a3UA8U4eIOo. Copy it and use it in the game. The blueprint split has a problem; revised code: EF01A67024u8eE1e9ieO. This set does not seem to be the latest progress, though. By 13x286.<br> Arknights: Endfield blueprint [2], share code EF018OI4eAaOE13uUI73. Copy it and use it in the game.<br> Arknights: Endfield blueprint [3], share code EF01Oe4Aa6oe7IuE9oe4. Copy it and use it in the game. Blueprint-split correction as above: EF01o5u21aiU36ioIieO.<br> Arknights: Endfield blueprint [4], share code EF0193aoE573ue4E5uI2. Copy it and use it in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8878fe3704f1d2ed.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-454d47cf4cf6ae09.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a289fcc8acabc17a.q90-5c57931e17a963fb.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-wtaH6muc44xSRMXmWrcqDs"></span></p><h3 id="marker-stone" tabindex="-1">Marker Stone <a class="header-anchor" href="#marker-stone" aria-label="Permalink to &quot;Marker Stone&quot;">​</a></h3><p>Three-in-one integrated toolkit (Yuanyuan Manor + everyday supplies + reserve materials):</p><p>Blueprint outputs:<br> Farming materials: Bottled Duskberry Juice, Starch, Double-Yummy Feed, Sugar, Chili Powder, Flour and Rapeseed Oil.<br> Everyday exploration/puzzles: 799 Bottled Water, 799 Bottled Liquid Xiranite, 799 Bottled Liquid Heavy Xiranite.<br> Reserve materials: 3250 Yazhen Syringe [A], 3250 Cuprium Parts, 799 Ferrium Parts and 799 LC Wuling Batteries.</p><p><span class="mark-blue">Blueprint code: EF013Eou7E3oEa96u0579</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0c22788646189df2.q90-ffa6175d4d81d5af.webp" alt="16 Automatic Maximum Gross Production"></p><p><span id="source-block-FBtPNvsLFil3Wtwnz99gI5"></span></p><h2 id="standalone-modules" tabindex="-1">Standalone Modules <a class="header-anchor" href="#standalone-modules" aria-label="Permalink to &quot;Standalone Modules&quot;">​</a></h2><p><span id="source-block-Z5vNKLZ8EC4EtG1KTC6C8F"></span></p><h3 id="xircon-line" tabindex="-1">Xircon Line <a class="header-anchor" href="#xircon-line" aria-label="Permalink to &quot;Xircon Line&quot;">​</a></h3><p>Arknights: Endfield blueprint [Single-Sided All-Condition Xircon], share code EF01u28U5Ie870a7AoOU. Copy it and use it in the game.<br> 15*21</p><p><span id="source-block-HUOTrAo1XGkxDqwoWUNxYD"></span></p><h3 id="heavy-xiranite" tabindex="-1">Heavy Xiranite <a class="header-anchor" href="#heavy-xiranite" aria-label="Permalink to &quot;Heavy Xiranite&quot;">​</a></h3><p>Arknights: Endfield blueprint [Four-Unit Heavy Xiranite], share code EF01I43EaUUUu9o45o08. Copy it and use it in the game.<br> 23*22, height 23</p><p><span id="source-block-A8b2BmNv3r8OczTH6mi4LB"></span></p><h3 id="copper-processing" tabindex="-1">Copper Processing <a class="header-anchor" href="#copper-processing" aria-label="Permalink to &quot;Copper Processing&quot;">​</a></h3><p>Arknights: Endfield blueprint [Temporary Refining], share code EF013Eo56eee8a510579. Copy it and use it in the game.<br> 12*21, double-sided</p><p>Arknights: Endfield blueprint [Separator Core], share code EF01U9ea48887OiI7Oa8. Copy it and use it in the game.<br> 12*15, double-sided</p><p>Arknights: Endfield blueprint [Two-Belt Cuprium], share code EF01o5uO5508u6330IieO. Copy it and use it in the game.</p><p>12*15, double-sided, exposed water pipes on both sides</p><p><span id="source-block-jb2LYfO4va5x22hZMk5JIm"></span></p><h3 id="sc-wuling-batteries" tabindex="-1">SC Wuling Batteries <a class="header-anchor" href="#sc-wuling-batteries" aria-label="Permalink to &quot;SC Wuling Batteries&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-87d2585d74b3e527.q90-8c276b21dca6cddc.webp" alt="16 Automatic Maximum Gross Production"></p><p>Arknights: Endfield blueprint [No Face Detected], share code EF01ao605oa6oA4A6oe5e. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Reconnecting, Please Wait], share code EF015i2O1i52iu9EueIoe. Copy it and use it in the game.</p><p><span id="source-block-h3O6ZElo5DYvpwQqWExr9k"></span></p><h3 id="ferrium-processing" tabindex="-1">Ferrium Processing <a class="header-anchor" href="#ferrium-processing" aria-label="Permalink to &quot;Ferrium Processing&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abd42c7b4bee2263.q90-fcf8ba08a760fb80.webp" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="K6uojhba5PhZY4h7JS1DHr"><p>赫塔 — Ferrium refining and shredding</p></div><p><span id="source-block-V6Z6WWObS8Sp9VROKaVcgK"></span></p><h3 id="xiranite" tabindex="-1">Xiranite <a class="header-anchor" href="#xiranite" aria-label="Permalink to &quot;Xiranite&quot;">​</a></h3><p><span class="mark-red">Where is it? Hurry up and bring it out!!!</span></p><p><span id="source-block-PSVH9EWPl3In6oiZbgmPV9"></span></p><h3 id="liquid-xiranite-full-storage-oscillation-module" tabindex="-1">Liquid Xiranite Full-Storage Oscillation Module <a class="header-anchor" href="#liquid-xiranite-full-storage-oscillation-module" aria-label="Permalink to &quot;Liquid Xiranite Full-Storage Oscillation Module&quot;">​</a></h3><p><span id="source-block-qFVfEvK9jO1NhKefnV1XSG"></span></p><h4 id="controlling-xiranite" tabindex="-1">Controlling Xiranite <a class="header-anchor" href="#controlling-xiranite" aria-label="Permalink to &quot;Controlling Xiranite&quot;">​</a></h4><p><span id="source-block-GiL6uZNnTppYmPRchrcBmr"></span></p><h4 id="controlling-water" tabindex="-1">Controlling Water <a class="header-anchor" href="#controlling-water" aria-label="Permalink to &quot;Controlling Water&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7c56052227e27422.q90-4b211e99002b0a11.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Filler: put 250 Jincao in every box except the unpowered one at the far left. Fill the unpowered tank with 4 miscellaneous items, and use enough Jincao Seeds to fill the length of the belt.</p><p>This should save a great many facilities, at the cost of only 4 pipe components. I have not compressed it yet, though ((</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-280aed2b84bcdf55.q90-653ca728b79d0e3c.webp" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="cXD5Oa5klddFZoIT9qBbsU"><p>The priorities are as shown in the figure.</p></div><p>Initial compression is complete. Preparing the unpowered tank takes quite a while; I do not know whether to optimize that.</p><p><s>Arknights: Endfield blueprint [Wuling Unpowered Tank], share code EF015i2eii8O2uaa0eIoe. Copy it and use it in the game.</s></p><p><s>Arknights: Endfield blueprint [Oscillating Liquid Xiranite], share code EF01E75U77u25o56E3uIa. Copy it and use it in the game.</s></p><p><strong>Already optimized by the esteemed 君</strong></p><p>Liquid full-storage oscillation EF01u28O96Ueo00EAoOU<br> 14*27</p><p>It should work if placed as shown.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7cbaefd4b1cd885b.q90-fe1d3cb93912abf0.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Candidate: EF01A67024u8eE1O91eO, wide-range oscillation, 21*18. Adjustable oscillation range: 28s~108s (12 filler items) to 3948~4028s (62 filler items).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-feec2a836390e201.q90-8cbde867b109ae36.webp" alt="16 Automatic Maximum Gross Production"></p><p>EF01o5u21aiU36iUIoeO is not narrow-range oscillation; its footprint is a little smaller, 20*18. Adjustable oscillation range: 34s~114s (12 filler items) to 114s~194s (13 filler items).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c2536bea61aa8e38.q90-ba4186b55889ea86.webp" alt="16 Automatic Maximum Gross Production"></p><p>EF0193ao7UE51e345uI2, narrow-range version, 20*18. Adjustable oscillation range: 22s~62s (6 filler items) to 502s to 542s (20 filler items).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9f420037eb66e90a.q90-117f16d292c0dd8e.webp" alt="16 Automatic Maximum Gross Production"></p><p>EF01E75i83014oaU3uIa, ultra-narrow-range version, 20*18. Adjustable oscillation range: 8s~28s (7 filler items) to 308s~328s (22 filler items).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fd8aab776a4fde48.q90-f329b117b2526f82.webp" alt="16 Automatic Maximum Gross Production"></p><p><span id="source-block-KGoyl1IImSJZnibL6nDWDF"></span></p><h3 id="xiragen" tabindex="-1">Xiragen <a class="header-anchor" href="#xiragen" aria-label="Permalink to &quot;Xiragen&quot;">​</a></h3><p><span id="source-block-bd3KuSLybokw1RKWgQVoj2"></span></p><h4 id="four-core-xiragen" tabindex="-1">Four-Core Xiragen <a class="header-anchor" href="#four-core-xiragen" aria-label="Permalink to &quot;Four-Core Xiragen&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d65940d65c763827.q90-cba6bbcbbf5c1244.webp" alt="16 Automatic Maximum Gross Production"></p><p>Arknights: Endfield blueprint [Two-Unit AND-Feed Xiragen], share code EF01Oe47ee3E4I3389oe4. Copy it and use it in the game.</p><p><span id="source-block-VI0K6hIG0gZuPIloebTgyJ"></span></p><h4 id="mixed-xiragen-aquagen-production" tabindex="-1">Mixed Xiragen/Aquagen Production <a class="header-anchor" href="#mixed-xiragen-aquagen-production" aria-label="Permalink to &quot;Mixed Xiragen/Aquagen Production&quot;">​</a></h4><p><span id="source-block-kWb3Jsyk9OsCbMnCJ8ZB5S"></span></p><h4 id="five-core-xiragen-alternative" tabindex="-1">Five-Core Xiragen (Alternative <a class="header-anchor" href="#five-core-xiragen-alternative" aria-label="Permalink to &quot;Five-Core Xiragen (Alternative&quot;">​</a></h4><p>Arknights: Endfield blueprint [Five Fluid-Gas Units], share code EF013Eou460iuau3U0579. Copy it and use it in the game.</p><p><span id="source-block-I6zAY6W2XBcbVSabVa6w2s"></span></p><h2 id="routing-xiragen-from-the-north-wuling-exclusion-zone" tabindex="-1">Routing Xiragen from the North Wuling Exclusion Zone <a class="header-anchor" href="#routing-xiragen-from-the-north-wuling-exclusion-zone" aria-label="Permalink to &quot;Routing Xiragen from the North Wuling Exclusion Zone&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-7ed15289ffeacc9c.q90-899dc838aff2d2a0.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-9e171bac57e90c75.q90-afaeee960e8ec8ac.webp" alt="Image"></td></tr></tbody></table><p><span class="mark-grey">The left option allows direct teleportation but needs an extra pair of conduits; the right requires traveling across the map and saves a pair of conduits.</span></p></div>',1)])])}const m=i(n,[["render",s]]);export{h as __pageData,m as default};
